\subsection*{Claim}
The named stochastic states used in the formalism are all normalized count-basis states with exactly the intended probability laws:
\[
P_{\mathrm{Pois}}(n)=e^{-\lambda}\frac{\lambda^n}{n!},\quad
P_B(n)=\binom{N}{n}p^n(1-p)^{N-n},
\]
\[
P_{NB}(n)=\binom{n+r-1}{n}(1-p)^rp^n,\quad
P_H(n)=\frac{\binom{K}{n}\binom{N-K}{M-n}}{\binom{N}{M}},
\]
with finite-support laws extended by zero outside their feasible support, and the Geometric law is exactly \(NB(1,p)\).

\subsection*{Derivation}
For Poisson, with \(\lambda>0\),
\begin{align}
\sum_{n=0}^{\infty}e^{-\lambda}\frac{\lambda^n}{n!}
&=e^{-\lambda}\sum_{n=0}^{\infty}\frac{\lambda^n}{n!}
=e^{-\lambda}e^{\lambda}=1.
\end{align}
For the coherent amplitude \(\alpha_n=e^{-\lambda/2}\lambda^{n/2}/\sqrt{n!}\), this gives \(|\alpha_n|^2=P_{\mathrm{Pois}}(n)\).

For Binomial, with \(0\leq p\leq1\),
\begin{align}
\sum_{n=0}^{N}\binom{N}{n}p^n(1-p)^{N-n}
&=(p+1-p)^N=1.
\end{align}
Thus \(\sum_{n=0}^{N}\sqrt{P_B(n)}|n\rangle\) is normalized and has zero mass for \(n>N\).

For Negative Binomial, with \(0<p<1\) and \(r\in\mathbb{N}\), the negative-binomial series gives
\begin{align}
\sum_{n=0}^{\infty}\binom{n+r-1}{n}(1-p)^rp^n
&=(1-p)^r\sum_{n=0}^{\infty}\binom{n+r-1}{n}p^n\\
&=(1-p)^r(1-p)^{-r}=1.
\end{align}
If \(r=1\), then \(\binom{n}{n}=1\), so
\begin{align}
P_{NB}(n;1,p)&=(1-p)p^n,
\end{align}
which is the zero-based Geometric law.

For Hypergeometric, define
\[
n_-:=\max\{0,M-(N-K)\},\qquad n_+:=\min\{K,M\}.
\]
Using the convention \(\binom{a}{b}=0\) when \(b<0\) or \(b>a\), Vandermonde's identity gives
\begin{align}
\sum_{n=n_-}^{n_+}\frac{\binom{K}{n}\binom{N-K}{M-n}}{\binom{N}{M}}
&=\frac{1}{\binom{N}{M}}\sum_{n=0}^{M}\binom{K}{n}\binom{N-K}{M-n}\\
&=\frac{\binom{N}{M}}{\binom{N}{M}}=1.
\end{align}
Therefore the state \(\sum_n\sqrt{P_S(n)}|n\rangle\) is normalized for each named family, and by orthonormality
\begin{align}
|\langle n|\psi_S\rangle|^2&=P_S(n).
\end{align}

\subsection*{Final Result}
\[
\boxed{\text{Poisson, Binomial, Negative Binomial, Geometric, and Hypergeometric laws are exact count-basis amplitude laws.}}
\]
\hfill$\blacksquare$

deeper_reasoning_3:
\subsection*{Claim}
Let \(P_\vartheta(k)>0\) be a differentiable one-parameter probability law with support independent of \(\vartheta\), and define real square-root amplitudes \(\alpha_k(\vartheta):=\sqrt{P_\vartheta(k)}\).  If the Fisher sum converges, then
\[
F_Q(\vartheta):=4\sum_k\left|\frac{d\alpha_k}{d\vartheta}\right|^2
=
\sum_k P_\vartheta(k)\left(\frac{d}{d\vartheta}\log P_\vartheta(k)\right)^2.
\]
Thus the amplitude-based quantum Fisher expression equals the classical Fisher information for the represented count law.  In particular,
\[
F_Q(\operatorname{Pois}(\lambda))=\frac{1}{\lambda},
\qquad
F_Q(\operatorname{Bin}(N,p))=\frac{N}{p(1-p)}.
\]

\subsection*{Derivation}
For every support point,
\begin{align}
\frac{d\alpha_k}{d\vartheta}
&=\frac{d}{d\vartheta}P_\vartheta(k)^{1/2}\\
&=\frac{1}{2}P_\vartheta(k)^{1/2}\frac{d}{d\vartheta}\log P_\vartheta(k).
\end{align}
Therefore
\begin{align}
4\sum_k\left|\frac{d\alpha_k}{d\vartheta}\right|^2
&=4\sum_k\frac{1}{4}P_\vartheta(k)\left(\frac{d}{d\vartheta}\log P_\vartheta(k)\right)^2\\
&=\sum_k P_\vartheta(k)\left(\frac{d}{d\vartheta}\log P_\vartheta(k)\right)^2.
\end{align}
For \(K\sim\operatorname{Pois}(\lambda)\),
\begin{align}
\frac{d}{d\lambda}\log P_\lambda(K)&=-1+\frac{K}{\lambda}=\frac{K-\lambda}{\lambda},\\
F_Q&=\mathbb{E}\left[\frac{(K-\lambda)^2}{\lambda^2}\right]
=\frac{\lambda}{\lambda^2}=\frac{1}{\lambda}.
\end{align}
For \(K\sim\operatorname{Bin}(N,p)\),
\begin{align}
\frac{d}{dp}\log P_p(K)
&=\frac{K}{p}-\frac{N-K}{1-p}
=\frac{K-Np}{p(1-p)},\\
F_Q&=\mathbb{E}\left[\frac{(K-Np)^2}{p^2(1-p)^2}\right]
=\frac{Np(1-p)}{p^2(1-p)^2}
=\frac{N}{p(1-p)}.
\end{align}

\subsection*{Final Result}
\[
\boxed{F_Q(\vartheta)=\sum_k P_\vartheta(k)\bigl(\partial_\vartheta\log P_\vartheta(k)\bigr)^2,\quad
F_Q(\operatorname{Pois})=1/\lambda,\quad F_Q(\operatorname{Bin})=N/[p(1-p)].}
\]
\hfill$\blacksquare$

deeper_reasoning_7:
\subsection*{Claim}
Let \(\hat H_S\) be Hermitian with orthonormal eigenmodes \(\{|\phi_j\rangle\}\) and eigenvalues \(E_j\).  If
\[
|\psi(0)\rangle=\sum_j c_j|\phi_j\rangle,
\qquad
|\psi(t)\rangle=\sum_j e^{-iE_jt}c_j|\phi_j\rangle,
\]
then \(|\psi(t)\rangle\) solves \(i\frac{d}{dt}|\psi(t)\rangle=\hat H_S|\psi(t)\rangle\), preserves norm, and induces the count law
\[
P_t(n)=\left|\sum_j e^{-iE_jt}c_j\langle n|\phi_j\rangle\right|^2.
\]
If the engineered stochastic state \(|\psi_S\rangle\) is a single eigenmode, then all count probabilities are stationary.  In particular, the Poisson coherent state engineered by \(\hat H_{\mathrm{Pois}}\) has a time-independent Poisson count law.

\subsection*{Derivation}
Differentiate the spectral expansion:
\begin{align}
\frac{d}{dt}|\psi(t)\rangle
&=\sum_j (-iE_j)e^{-iE_jt}c_j|\phi_j\rangle.
\end{align}
Multiplying by \(i\) gives
\begin{align}
i\frac{d}{dt}|\psi(t)\rangle
&=\sum_j E_je^{-iE_jt}c_j|\phi_j\rangle\\
&=\sum_j e^{-iE_jt}c_j\hat H_S|\phi_j\rangle\\
&=\hat H_S\sum_j e^{-iE_jt}c_j|\phi_j\rangle
=\hat H_S|\psi(t)\rangle.
\end{align}
The initial condition follows by setting \(t=0\).  Norm preservation follows from orthonormality:
\begin{align}
\langle\psi(t)|\psi(t)\rangle
&=\sum_{j,k}e^{iE_jt}e^{-iE_kt}c_j^*c_k\langle\phi_j|\phi_k\rangle\\
&=\sum_j |c_j|^2
=\langle\psi(0)|\psi(0)\rangle.
\end{align}
Projecting onto the count basis gives
\begin{align}
\langle n|\psi(t)\rangle
&=\sum_j e^{-iE_jt}c_j\langle n|\phi_j\rangle,\\
P_t(n)&=|\langle n|\psi(t)\rangle|^2.
\end{align}
If \(|\psi(0)\rangle=|\phi_s\rangle\), then \(|\psi(t)\rangle=e^{-iE_st}|\phi_s\rangle\), so
\begin{align}
P_t(n)&=|e^{-iE_st}\langle n|\phi_s\rangle|^2=|\langle n|\phi_s\rangle|^2.
\end{align}
For the Poisson construction, \(|\alpha\rangle\) is an eigenstate of \(\hat H_{\mathrm{Pois}}\), hence its count probabilities remain
\begin{align}
P_t(n)&=|\langle n|\alpha\rangle|^2=e^{-|\alpha|^2}\frac{|\alpha|^{2n}}{n!}
\end{align}
for all \(t\).

\subsection*{Final Result}
\[
\boxed{\text{Spectral dynamics preserve norm, give explicit time-dependent count laws, and make engineered eigenstate laws stationary.}}
\]
\hfill$\blacksquare$
